/** void FadeOutBody(struct MusicPlayerInfo *mplayInfo) */
export function FadeOutBody(mplayInfo: any): any {
  let i: any = null;
      let track: any = null;
      let fadeOV: any = null;

      if (mplayInfo.fadeOI == 0)
          return;
      if (--mplayInfo.fadeOC != 0)
          return;

      mplayInfo.fadeOC = mplayInfo.fadeOI;

      if (mplayInfo.fadeOV & FADE_IN)
      {
          if ((mplayInfo.fadeOV += (4 << FADE_VOL_SHIFT)) >= (64 << FADE_VOL_SHIFT))
          {
              mplayInfo.fadeOV = (64 << FADE_VOL_SHIFT);
              mplayInfo.fadeOI = 0;
          }
      }
      else
      {
          if ((mplayInfo.fadeOV -= (4 << FADE_VOL_SHIFT)) <= 0)
          {
              i = mplayInfo.trackCount;
              track = mplayInfo.tracks;

              while (i > 0)
              {
                  let val: any = null;

                  TrackStop(mplayInfo, track);

                  val = TEMPORARY_FADE;
                  fadeOV = mplayInfo.fadeOV;
                  val &= fadeOV;

                  if (!val)
                      track.flags = 0;

                  i--;
                  track++;
              }

              if (mplayInfo.fadeOV & TEMPORARY_FADE)
                  mplayInfo.status |= MUSICPLAYER_STATUS_PAUSE;
              else
                  mplayInfo.status = MUSICPLAYER_STATUS_PAUSE;

              mplayInfo.fadeOI = 0;
              return;
          }
      }

      i = mplayInfo.trackCount;
      track = mplayInfo.tracks;

      while (i > 0)
      {
          if (track.flags & MPT_FLG_EXIST)
          {
              fadeOV = mplayInfo.fadeOV;

              track.volX = (fadeOV >> FADE_VOL_SHIFT);
              track.flags |= MPT_FLG_VOLCHG;
          }

          i--;
          track++;
      }
}

/** void TrkVolPitSet(struct MusicPlayerInfo *mplayInfo, struct MusicPlayerTrack *track) */
export function TrkVolPitSet(mplayInfo: any, track: any): any {
  if (track.flags & MPT_FLG_VOLSET)
      {
          let x: any = null;
          let y: any = null;

          x = (track.vol * track.volX) >> 5;

          if (track.modT == 1)
              x = (x * (track.modM + 128)) >> 7;

          y = 2 * track.pan + track.panX;

          if (track.modT == 2)
              y += track.modM;

          if (y < -128)
              y = -128;
          else if (y > 127)
              y = 127;

          track.volMR = ((y + 128) * x) >> 8;
          track.volML = ((127 - y) * x) >> 8;
      }

      if (track.flags & MPT_FLG_PITSET)
      {
          let bend: any = track.bend * track.bendRange;
          let x: any = (track.tune + bend)
                * 4
                + (track.keyShift << 8)
                + (track.keyShiftX << 8)
                + track.pitX;

          if (track.modT == 0)
              x += 16 * track.modM;

          track.keyM = x >> 8;
          track.pitM = x;
      }

      track.flags &= ~(MPT_FLG_PITSET | MPT_FLG_VOLSET);
}

/** u32 MidiKeyToCgbFreq(u8 chanNum, u8 key, u8 fineAdjust) */
export function MidiKeyToCgbFreq(chanNum: any, key: any, fineAdjust: any): any {
  if (chanNum == 4)
      {
          if (key <= 20)
          {
              key = 0;
          }
          else
          {
              key -= 21;
              if (key > 59)
                  key = 59;
          }

          return gNoiseTable[key];
      }
      else
      {
          let val1: any = null;
          let val2: any = null;

          if (key <= 35)
          {
              fineAdjust = 0;
              key = 0;
          }
          else
          {
              key -= 36;
              if (key > 130)
              {
                  key = 130;
                  fineAdjust = 255;
              }
          }

          val1 = gCgbScaleTable[key];
          val1 = gCgbFreqTable[val1 & 0xF] >> (val1 >> 4);

          val2 = gCgbScaleTable[key + 1];
          val2 = gCgbFreqTable[val2 & 0xF] >> (val2 >> 4);

          return val1 + ((fineAdjust * (val2 - val1)) >> 8) + 2048;
      }
}

