/** void ply_memacc(struct MusicPlayerInfo *mplayInfo, struct MusicPlayerTrack *track) */
export function ply_memacc(mplayInfo: any, track: any): any {
  let op: any = null;
      let addr: any = null;
      let data: any = null;

      op = track.cmdPtr;
      track.cmdPtr++;

      addr = mplayInfo.memAccArea + track.cmdPtr;
      track.cmdPtr++;

      data = track.cmdPtr;
      track.cmdPtr++;

      switch (op)
      {
      case 0:
          addr = data;
          return;
      case 1:
          addr += data;
          return;
      case 2:
          addr -= data;
          return;
      case 3:
          addr = mplayInfo.memAccArea[data];
          return;
      case 4:
          addr += mplayInfo.memAccArea[data];
          return;
      case 5:
          addr -= mplayInfo.memAccArea[data];
          return;
      case 6:
          
          return;
      case 7:
          
          return;
      case 8:
          
          return;
      case 9:
          
          return;
      case 10:
          
          return;
      case 11:
          
          return;
      case 12:
          
          return;
      case 13:
          
          return;
      case 14:
          
          return;
      case 15:
          
          return;
      case 16:
          
          return;
      case 17:
          
          return;
      default:
          return;
      }

  // LABEL: cond_true:
      {
           
          (gMPlayJumpTable[1])(mplayInfo, track);
          return;
      }

  // LABEL: cond_false:
      track.cmdPtr += 4;
}

