/** void SetPokemonCryVolume(u8 val) */
export function SetPokemonCryVolume(val: any): any {
  gPokemonCrySong.volumeValue = val & 0x7F;
}

/** void SetPokemonCryPanpot(s8 val) */
export function SetPokemonCryPanpot(val: any): any {
  gPokemonCrySong.panValue = (val + C_V) & 0x7F;
}

/** void SetPokemonCryPitch(s16 val) */
export function SetPokemonCryPitch(val: any): any {
  let b: any = val + 0x80;
      let a: any = gPokemonCrySong.tuneValue2 - gPokemonCrySong.tuneValue;
      gPokemonCrySong.tieKeyValue = (b >> 8) & 0x7F;
      gPokemonCrySong.tuneValue = (b >> 1) & 0x7F;
      gPokemonCrySong.tuneValue2 = (a + ((b >> 1) & 0x7F)) & 0x7F;
}

/** void SetPokemonCryLength(u16 val) */
export function SetPokemonCryLength(val: any): any {
  gPokemonCrySong.length = val;
}

/** void SetPokemonCryRelease(u8 val) */
export function SetPokemonCryRelease(val: any): any {
  gPokemonCrySong.releaseValue = val;
}

/** void SetPokemonCryProgress(u32 val) */
export function SetPokemonCryProgress(val: any): any {
  gPokemonCrySong.unkCmd0DParam = val;
}

/** bool32 IsPokemonCryPlaying(struct MusicPlayerInfo *mplayInfo) */
export function IsPokemonCryPlaying(mplayInfo: any): any {
  let track: any = mplayInfo.tracks;

      if (track.chan && track.chan.track == track)
          return TRUE;
      else
          return FALSE;
}

/** void SetPokemonCryChorus(s8 val) */
export function SetPokemonCryChorus(val: any): any {
  if (val)
      {
          gPokemonCrySong.trackCount = 2;
          gPokemonCrySong.tuneValue2 = (val + gPokemonCrySong.tuneValue) & 0x7F;
      }
      else
      {
          gPokemonCrySong.trackCount = 1;
      }
}

/** void SetPokemonCryStereo(u32 val) */
export function SetPokemonCryStereo(val: any): any {
  let soundInfo: any = SOUND_INFO_PTR;

      if (val)
      {
          REG_SOUNDCNT_H = SOUND_B_TIMER_0 | SOUND_B_LEFT_OUTPUT
                         | SOUND_A_TIMER_0 | SOUND_A_RIGHT_OUTPUT
                         | SOUND_ALL_MIX_FULL;
          soundInfo.mode &= ~1;
      }
      else
      {
          REG_SOUNDCNT_H = SOUND_B_TIMER_0 | SOUND_B_LEFT_OUTPUT | SOUND_B_RIGHT_OUTPUT
                         | SOUND_A_TIMER_0 | SOUND_A_LEFT_OUTPUT | SOUND_A_RIGHT_OUTPUT
                         | SOUND_B_MIX_HALF | SOUND_A_MIX_HALF | SOUND_CGB_MIX_FULL;
          soundInfo.mode |= 1;
      }
}

/** void SetPokemonCryPriority(u8 val) */
export function SetPokemonCryPriority(val: any): any {
  gPokemonCrySong.priority = val;
}

